{
  "title": "Flavours and Faces of the City",
  "summary": "A slower day around the historic centre and Roma Norte, with a market-style lunch, a proper evening meal and just enough sights to leave room for snacking.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "The great temple still anchors the morning, though we let the old must-do go and simply enjoy it as a fine piece of history.",
      "must_do_id": null
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle wander through Roma Norte works up an appetite and gives the photographers their street scenes.",
      "must_do_id": null
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Lalo! keeps things casual and vegetarian-friendly, with room for a market snack later.",
      "must_do_id": null
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chapultepec gives us green air and a slower pace before the evening meal.",
      "must_do_id": null
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Pujol is the proper meal of the day, a long vegetarian-friendly dinner to end on a high note.",
      "must_do_id": null
    }
  ]
}
